export function icon(name, size = 16, className = "") {
  const content = SVG_ICONS[name] || SVG_ICONS.activity;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="kasp-icon ${className}">${content}</svg>`;
}
